(356015, 28061, 8860, '<td valign="top">Whether or not it was actually hot doesn''t matter. This gives the illusion of blistering heat haze. Nice idea and there''s enough detail to make it work. [7]</td>', 'Whether or not it was actually hot doesn''t matter. This gives the illusion of blistering heat haze. Nice idea and there''s enough detail to make it work. [7]', '2003-07-14 13:11:35.000000', NULL, 1),
(356021, 28707, 8860, '<td valign="top">This doesn''t necessarily indicate soaring temperatures but it does look like a warm climate and is certainly a beautiful shot, with great colour and atmosphere. [6]</td>', 'This doesn''t necessarily indicate soaring temperatures but it does look like a warm climate and is certainly a beautiful shot, with great colour and atmosphere. [6]', '2003-07-14 13:16:40.000000', NULL, 1),
