(356439, 28749, 6600, '<td valign="top">Certainly looks cool, well composed.  Good job.  Critique: White area is void of much texture or detail, maybe a bit overexposed.</td>', 'Certainly looks cool, well composed.  Good job.  Critique: White area is void of much texture or detail, maybe a bit overexposed.', '2003-07-15 00:11:41.000000', NULL, 1),
(356441, 28124, 6600, '<td valign="top">Nice colors (like the transition from blue to brown), well composed,  good job.</td>', 'Nice colors (like the transition from blue to brown), well composed,  good job.', '2003-07-15 00:13:38.000000', NULL, 1),
