(356477, 28373, 326, '<td valign="top">Looks blazing HOT!</td>', 'Looks blazing HOT!', '2003-07-15 00:44:38.000000', NULL, 1),
(356478, 28454, 8953, '<td valign="top">Love the colors on this shot, but having trouble finding a grounding point for my eyes..I still felt it had the elements for the contest.7</td>', 'Love the colors on this shot, but having trouble finding a grounding point for my eyes..I still felt it had the elements for the contest.7', '2003-07-15 00:45:51.000000', NULL, 1),
