(358178, 28506, 3290, '<td valign="top">Way too small - try making your submissions bigger. You can go up to 640 pixels on a side.</td>', 'Way too small - try making your submissions bigger. You can go up to 640 pixels on a side.', '2003-07-16 08:54:05.000000', NULL, 1),
(358183, 28544, 3290, '<td valign="top">Very nice. I''d have pulled back a bit so we could see more of the berries/twigs as a whole. But this makes me feel nicely chilly.</td>', 'Very nice. I''d have pulled back a bit so we could see more of the berries/twigs as a whole. But this makes me feel nicely chilly.', '2003-07-16 08:55:18.000000', NULL, 1),
(358198, 28351, 7628, '<td valign="top">An adorable composition.  Captures not only the feeling of a hot beach and the cool waves but the fun spirit of the child.  Wonder what it would look like with a greater DOF and the waves crisp?</td>', 'An adorable composition.  Captures not only the feeling of a hot beach and the cool waves but the fun spirit of the child.  Wonder what it would look like with a greater DOF and the waves crisp?', '2003-07-16 09:09:37.000000', NULL, 1),
(358201, 28092, 3290, '<td valign="top">This gives a great sense of heat - and I can smell the smoke. Good one.</td>', 'This gives a great sense of heat - and I can smell the smoke. Good one.', '2003-07-16 09:10:16.000000', NULL, 1),
(358204, 28678, 7628, '<td valign="top">Interesting idea.  Took me a while to see what was the ice - the background makes it confusing.  I think it would work better if the skin and ice werre seen against an entirely black background, and the spot of the "kiss" was centered or on a "thirds" line.</td>', 'Interesting idea.  Took me a while to see what was the ice - the background makes it confusing.  I think it would work better if the skin and ice werre seen against an entirely black background, and the spot of the "kiss" was centered or on a "thirds" line.', '2003-07-16 09:12:10.000000', NULL, 1),
(358306, 28632, 7190, '<td valign="top">find the red sign distrracting but you did capture the heat</td>', 'find the red sign distrracting but you did capture the heat', '2003-07-16 10:22:02.000000', NULL, 1),
(358308, 28639, 3290, '<td valign="top">Nice. It''s a little dark and I feel it would better convey chilliness if it were lighter, but I still like it a lot.</td>', 'Nice. It''s a little dark and I feel it would better convey chilliness if it were lighter, but I still like it a lot.', '2003-07-16 10:25:42.000000', NULL, 1),
(358309, 28591, 3290, '<td valign="top">I like the idea, but the lighting needs some work - it''s a bit flat at the moment. Looks like you used a flash - perhaps try a longer exposure with ambient light?</td>', 'I like the idea, but the lighting needs some work - it''s a bit flat at the moment. Looks like you used a flash - perhaps try a longer exposure with ambient light?', '2003-07-16 10:26:46.000000', NULL, 1),
(358312, 28350, 3290, '<td valign="top">Nice melting. Focus looks a little soft. And it might have more impact in brighter (sun?) light.</td>', 'Nice melting. Focus looks a little soft. And it might have more impact in brighter (sun?) light.', '2003-07-16 10:28:49.000000', NULL, 1),
(358313, 27782, 3290, '<td valign="top">I like the picture a lot, just not sure it conveys temperature very well.</td>', 'I like the picture a lot, just not sure it conveys temperature very well.', '2003-07-16 10:29:27.000000', NULL, 1),
(358316, 28088, 3290, '<td valign="top">I like this one. Well done. Seems like cold is easier to portray than heat.</td>', 'I like this one. Well done. Seems like cold is easier to portray than heat.', '2003-07-16 10:31:02.000000', NULL, 1),
(358317, 28400, 3290, '<td valign="top">Just as I leave a comment that cold is easier to portray than heat - alongcomes this one to prove me wrong. I really like this, it portrays heat well and with a twist.</td>', 'Just as I leave a comment that cold is easier to portray than heat - alongcomes this one to prove me wrong. I really like this, it portrays heat well and with a twist.', '2003-07-16 10:31:52.000000', NULL, 1),
(358318, 28065, 3290, '<td valign="top">That''s hot alright. It''s a little dark and would make me sweat better if a bit lighter, I think. Perhaps including a person in the shot would help, too?</td>', 'That''s hot alright. It''s a little dark and would make me sweat better if a bit lighter, I think. Perhaps including a person in the shot would help, too?', '2003-07-16 10:32:37.000000', NULL, 1),
(358319, 28225, 3290, '<td valign="top">She looks it, too. Well done.</td>', 'She looks it, too. Well done.', '2003-07-16 10:33:12.000000', NULL, 1),
(358322, 28313, 3290, '<td valign="top">Nice, but flash is a little harsh. Might have been nice to try this with backlit steam and ambient light.</td>', 'Nice, but flash is a little harsh. Might have been nice to try this with backlit steam and ambient light.', '2003-07-16 10:34:32.000000', NULL, 1),
(358642, 28535, 10275, '<td valign="top">One of my favourites in this category. Sizzling hot !! I hope this wins!</td>', 'One of my favourites in this category. Sizzling hot !! I hope this wins!', '2003-07-16 13:32:23.000000', NULL, 1),
