(358822, 28707, 6405, '<td valign="top">excellent cloud color,but I would prefer the buildings in the middle,8 from me!</td>', 'excellent cloud color,but I would prefer the buildings in the middle,8 from me!', '2003-07-16 14:50:35.000000', NULL, 1),
(359347, 28256, 3447, '<td valign="top">Very nice light with interesting shadow and composition.   Can''t imagine where this was taken, Richard.    8</td>', 'Very nice light with interesting shadow and composition.   Can''t imagine where this was taken, Richard.    8', '2003-07-16 21:49:05.000000', NULL, 1),
